WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, ROW_NUMBER() OVER (PARTITION BY p.PostTypeId ORDER BY p.Score DESC NULLS FIRST, p.ViewCount DESC NULLS FIRST) AS Rank FROM Posts AS p WHERE p.CreationDate >= CAST('2024-10-01' AS Nullable(DATE)) - INTERVAL '1' YEAR), UserReputation AS (SELECT u.Id AS UserId, u.Reputation, COUNT(b.Id) AS BadgeCount FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id, u.Reputation), ClosedPosts AS (SELECT ph.PostId, ph.CreationDate, ph.UserId, GROUP_CONCAT(CASE WHEN ph.PostHistoryTypeId = 10 THEN cr.Name END, ', ') AS CloseReasons FROM PostHistory AS ph JOIN CloseReasonTypes AS cr ON CAST(ph.Comment AS Nullable(Int32)) = cr.Id WHERE ph.PostHistoryTypeId = 10 GROUP BY ph.PostId, ph.CreationDate, ph.UserId) SELECT rp.PostId, rp.Title, rp.CreationDate, rp.Score, rp.ViewCount, ur.Reputation, ur.BadgeCount, cp.CloseReasons FROM RankedPosts AS rp LEFT JOIN UserReputation AS ur ON ur.UserId = rp.PostId LEFT JOIN ClosedPosts AS cp ON cp.PostId = rp.PostId WHERE rp.Rank <= 5 ORDER BY rp.ViewCount DESC NULLS FIRST, rp.Score DESC NULLS FIRST LIMIT 50